  try { return JSON.parse(String(java.ajax("https://" + host + "/webapi/novel/chapterGetInfo?cid=" + cid + "&server=0" + opt))); } catch (e) { return null; }
}
function valid(token) {
  try {
    var u = JSON.parse(String(java.ajax("https://m.gongzicp.com/webapi/user/getUserInfo,{\"headers\":{\"token\":\"" + token + "\",\"client\":\"h5\"}}")));
    return String(u.code) == "200";
  } catch (e) { return true; }
}
function fromWebView() {
  try { return String(java.webView("", "https://m.gongzicp.com/", "sessionStorage.getItem('token') || ''") || ""); } catch (e) { return ""; }
}
function dec(c) {
  try { return String(java.aesBase64DecodeToString(c, "u0LRrbu$Enm84koA", "AES/CBC/PKCS5Padding", "$h$b3!iGzsYnnshj") || ""); } catch (e) { return ""; }
}
var token = String(java.get("cp_token") || "");
if (!token) {
  token = fromWebView();
  if (token) java.put("cp_token", token);
}
if (!token) return "【需要登录】请在书源菜单点「登录」，在应用内网页里登录长佩账号，然后刷新本章。";
var r = pull(token, "m.gongzicp.com");
if (r === null) r = pull(token, "www.gongzicp.com");
if (r === null) return "【获取失败】网络异常，请检查网络后重试。";
if (String(r.code) == "9996") { java.put("cp_token", ""); return "【登录已失效】请重新登录长佩账号后刷新本章。"; }
var ci = r.data && r.data.chapterInfo;
if (!ci) return "【获取失败】" + (r.msg || "接口无数据");
var txt = "";
if (ci.content && ci.content.length > 40) txt = dec(ci.content);
var check = parseInt(String((r.data && r.data.check) || 0)) || 0;
if (!txt) {
  if (ci.chapterPrice > 0) return "【本章需订阅】" + ci.chapterPrice + " 玉佩（账号内未购买本章）";
  // 第一步：尝试应用内网页已有的（可能已验证过的）登录态
  var t2 = fromWebView();
  if (t2 && t2 != token && valid(t2)) {
    var r2 = pull(t2, "m.gongzicp.com");
    var ci2 = r2 && r2.data && r2.data.chapterInfo;
    if (ci2 && ci2.content && ci2.content.length > 40) {
      var t2t = dec(ci2.content);
      if (t2t) { token = t2; ci = ci2; txt = t2t; java.put("cp_token", t2); }
    }
  }
}
if (!txt) {
  var loginOk = valid(token);
  if (!loginOk) { java.put("cp_token", ""); return "【登录已失效】请在弹出的验证网页里登录长佩账号并完成滑块，然后刷新本章。"; }
  if (check < 3) return "【正文为空】站点未下发正文（check=" + check + "），请几分钟后重试。";
  // 第二步：配额用尽，主动弹出验证网页（章节页），用户完成滑块后自动继续
  var popupOk = true;
  try { java.startBrowserAwait("https://m.gongzicp.com/read-" + cid + ".html", "长佩·滑块验证"); }
  catch (e) { popupOk = false; }
  var t3 = fromWebView();
  if (!t3) t3 = token;
  var r3 = null, ci3 = null, t3t = "";
  if (valid(t3)) {
    r3 = pull(t3, "m.gongzicp.com");
    if (r3 === null) r3 = pull(t3, "www.gongzicp.com");
    ci3 = r3 && r3.data && r3.data.chapterInfo;
    if (ci3 && ci3.content && ci3.content.length > 40) t3t = dec(ci3.content);
  }
  if (t3t) {
    if (t3 != token) java.put("cp_token", t3);
    ci = ci3; txt = t3t;
  } else {
    if (!popupOk) return "【需要验证】当前阅读版本不支持自动弹出验证窗口。请点书源菜单「登录」，在应用内网页进入本书章节页完成滑块后刷新本章。";
    if (!t3 || !valid(t3)) return "【验证未完成】请在弹出的网页里先登录长佩账号，再进入章节完成滑块验证，然后刷新本章。";
    return "【验证未通过】滑块未完成或未生效，请重试本章；若多次失败请等 30-60 分钟后再试。";
  }
}
txt = String(txt).replace(/\r/g, "").replace(/\n[ \t\u3000]*\n/g, "\n\n").replace(/[ \t\u3000]+\n/g, "\n").replace(/\n{3,}/g, "\n\n").replace(/^\s+|\s+$/g, "");
if (txt.indexOf("<") < 0) txt = txt.replace(/\n/g, "<br>");
if (ci.postscript) txt = txt + "<br><br>【作者有话说】" + ci.postscript;
return txt;
